#!/usr/bin/env python3
"""Inspect report.pdf page contents to diagnose current state."""
import os
import sys

from pypdf import PdfReader


def find_report(root):
    for dirpath, _dirnames, filenames in os.walk(root):
        for name in filenames:
            if name.lower() == 'report.pdf':
                return os.path.join(dirpath, name)
    return None


def main():
    cwd = os.getcwd()
    src = find_report(cwd)
    if src is None:
        for root in ['/workspace', '/tmp', '/home', '/root', '/data']:
            if os.path.isdir(root):
                src = find_report(root)
                if src:
                    break
    if src is None:
        print("ERROR: report.pdf not found")
        sys.exit(2)
    print("Inspecting:", src)
    print("File size:", os.path.getsize(src), "bytes")

    reader = PdfReader(src)
    print("Total pages:", len(reader.pages))
    for i, page in enumerate(reader.pages):
        text = page.extract_text() or ''
        print(f"--- Page {i + 1} text ---")
        print(repr(text[:500]))


if __name__ == '__main__':
    main()

