#!/usr/bin/env python3
"""Verify report.pdf now has a cover page with the title and current date."""
import datetime
import os
import sys

from pypdf import PdfReader


def find_report(root):
    for dirpath, _dirnames, filenames in os.walk(root):
        for name in filenames:
            if name.lower() == 'report.pdf':
                return os.path.join(dirpath, name)
    return None


def main():
    cwd = os.getcwd()
    src = find_report(cwd)
    if src is None:
        for root in ['/workspace', '/tmp', '/home', '/root', '/data']:
            if os.path.isdir(root):
                src = find_report(root)
                if src:
                    break
    if src is None:
        print("ERROR: report.pdf not found")
        sys.exit(2)
    print("Verifying:", src)

    reader = PdfReader(src)
    total = len(reader.pages)
    print("Total pages:", total)
    if total < 2:
        print("ERROR: expected at least 2 pages (cover + original content)")
        sys.exit(3)

    cover_text = reader.pages[0].extract_text() or ''
    print("--- Page 1 text ---")
    print(cover_text)

    ok = True
    if 'Annual Financial Report' not in cover_text:
        print("ERROR: title missing on cover page")
        ok = False
    today = datetime.date.today().strftime('%B %d, %Y')
    if today not in cover_text:
        print(f"ERROR: current date ({today}) missing on cover page")
        ok = False
    if not ok:
        sys.exit(4)

    print("VERIFIED: cover page present with title and current date", today)


if __name__ == '__main__':
    main()

